update employee
employee_name=#{employeeName}, employee_code=#{employeeCode}, employee_phone_number=#{employeePhoneNumber}, employee_addr=#{employeeAddr}, employee_month_salary=#{employeeMonthSalary}, employee_year_salary=#{employeeYearSalary}, employee_description=#{employeeDescription}, employee_position_name=#{employeePositionName}, employee_dep_name=#{employeeDepName},
where merchant_id=#{merchantId} and is_delete=false and employee_id=#{employeeId}

update employee set employee_person_image_addr=#{addr}
where merchant_id=#{merchantId} and is_delete=false and employee_id=#{employeeId}
and employee_person_image_addr
=#{oldAddr}
 is null
